            flush_interval=_checkpoint_flush_interval(
                getattr(self.run_store, "_redis_client", None)
            ),
        )
        magi_role_delta_buffer = _MagiRoleDeltaBuffer(
            run_id=run.id,
            worker_id=claimed_worker_id,
            run_store=self.run_store,
            redis_publish_fn=lambda run_id, payload, code: self._publish_live_event(
                run_id, payload, code
            ),
            ownership_lost_event=ownership_lost_event,
            flush_interval=_checkpoint_flush_interval(
                getattr(self.run_store, "_redis_client", None)
            ),
        )
        heartbeat_stop = threading.Event()
        heartbeat_thread = threading.Thread(
            target=self._heartbeat_and_flush_loop,
            args=(
                run.id,
                claimed_worker_id,
                heartbeat_stop,
                ownership_lost_event,
                delta_buffer,
                magi_role_delta_buffer,
            ),
            daemon=True,
        )
        heartbeat_thread.start()
        try:
            router = self._build_router(run)
            last_normalized_inputs = None

            def _state_listener(state, turn):
                nonlocal last_normalized_inputs
                self._emit_state(run.id, claimed_worker_id, state, turn)
                if (
                    getattr(run, "run_kind", MESSAGE_RUN_KIND) or MESSAGE_RUN_KIND
                ) != MESSAGE_RUN_KIND:
                    return
                normalized_inputs = _turn_normalized_inputs(run.request_content, turn)
                if normalized_inputs == last_normalized_inputs:
                    return
                self.run_store.replace_normalized_inputs_for_worker(
                    run.id,
                    claimed_worker_id,
                    normalized_inputs,
                )
                last_normalized_inputs = normalized_inputs

            router.set_state_listener(_state_listener)

            def _event_listener(event_type, payload):
                if event_type == "text_delta":
                    delta_buffer.push((payload or {}).get("delta", ""))
                    return
                if event_type == "magi_role_start":
                    magi_role_delta_buffer.begin_entry(payload)
                if event_type == "magi_role_text_delta":
                    magi_role_delta_buffer.push(payload)
                    return
                if event_type == "magi_role_complete":
                    magi_role_delta_buffer.flush_entry(payload)
                self._emit_event(run.id, claimed_worker_id, event_type, payload)
                if event_type == "magi_role_complete":
                    magi_role_delta_buffer.finish_entry(payload)

            router.set_event_listener(_event_listener)

            if (
                getattr(run, "run_kind", MESSAGE_RUN_KIND) or MESSAGE_RUN_KIND
            ) == AUTO_NAME_RUN_KIND:
                turn = router.run_auto_name_follow_up()
            elif getattr(run, "pause_state_json", None) and (run.magi or "off") in {
                "full",
                "lite",
            }:
                turn = router.run_magi_resumption(
                    getattr(run, "pause_state_json", None),
                    stream_response=True,
                    magi=run.magi,
                )
            else:
                turn = router.run_turn(
                    run.request_content, stream_response=True, magi=run.magi
                )
            if self.run_store.is_cancel_requested(run.id):
                raise RunCancelledError("Run cancelled.")
            if turn is None:
                raise RuntimeError("Worker completed without a router turn.")

            delta_buffer.flush()
            magi_role_delta_buffer.flush()
            if (
                getattr(run, "run_kind", MESSAGE_RUN_KIND) or MESSAGE_RUN_KIND
            ) == AUTO_NAME_RUN_KIND:
                self._complete_background_run(run, claimed_worker_id, turn)
            else:
                self._queue_auto_name_run(run, turn, claimed_worker_id)
                self._complete_run(run, claimed_worker_id, turn)
        except RunOwnershipLostError:
            try:
                delta_buffer.flush()
                magi_role_delta_buffer.flush()
            except RunOwnershipLostError:
                pass
        except RunCancelledError as exc:
            try:
                delta_buffer.flush()
                magi_role_delta_buffer.flush()
            except RunOwnershipLostError:
                return
            self._cancel_run(run, claimed_worker_id, str(exc) or "Run cancelled.")
        except RunPausedError as exc:
            try:
                delta_buffer.flush()
                magi_role_delta_buffer.flush()
            except RunOwnershipLostError:
                return
            self.run_store.mark_paused(
                run.id,
                worker_id=claimed_worker_id,
                pause_state=getattr(exc, "pause_state", None) or {},
                event_payload=getattr(exc, "payload", None)
                or {"message": "Run paused."},
            )
        except RouterExecutionError as exc:
            try:
                delta_buffer.flush()
                magi_role_delta_buffer.flush()
            except RunOwnershipLostError:
                return
            self._fail_run(run, claimed_worker_id, str(exc))
        except Exception as exc:
            try:
                delta_buffer.flush()
                magi_role_delta_buffer.flush()
            except RunOwnershipLostError:
                return
            self._fail_run(run, claimed_worker_id, str(exc))
        finally:
            heartbeat_stop.set()
            heartbeat_thread.join(timeout=2)

    def _worker_loop(self, slot_index):
        claimed_worker_id = f"{self.worker_id}:{slot_index}"
        poll_seconds = max(0.05, float(self.settings.chat_run_worker_poll_ms) / 1000.0)
        wakeup_sub = None
        redis_client = _get_redis_client()
        if redis_client is not None:
            try:
                from streaming.redis_events import subscribe_wakeup

                wakeup_sub = subscribe_wakeup(redis_client)
            except Exception:
                wakeup_sub = None
        try:
            while not self._stop_event.is_set():
                run = self.run_store.claim_next_run(
                    claimed_worker_id, self.settings.chat_run_lease_seconds
                )
                if run is None:
                    if wakeup_sub is not None:
                        try:
                            wakeup_sub.get_message(timeout=poll_seconds)
                        except Exception:
                            self._stop_event.wait(poll_seconds)
                    else:
                        self._stop_event.wait(poll_seconds)
                    continue
                self._handle_claimed_run(run, claimed_worker_id)
        finally:
            if wakeup_sub is not None:
                try:
                    wakeup_sub.unsubscribe()
                    wakeup_sub.close()
                except Exception:
                    pass

    def run(self):
        concurrency = max(1, int(self.settings.chat_run_worker_concurrency))
        with ThreadPoolExecutor(max_workers=concurrency) as executor:
            futures = [
                executor.submit(self._worker_loop, index)
                for index in range(concurrency)
            ]
            try:
                for future in futures:
                    future.result()
            except KeyboardInterrupt:
                self.stop()
            finally:
                self.stop()

    def stop(self):
        self._stop_event.set()


