    if item_type == "constraint":
        return f"{item.get('constraint_key', '')}={item.get('constraint_value', '')}"
    if item_type == "preference":
        return f"{item.get('preference_key', '')}={item.get('preference_value', '')}"
    return _truncate(str(item))


